INSERT INTO "public"."llm_logs" VALUES ('2b135763-ca59-4be7-b743-bfd22a03ae1f', 'parseJobDescription', 'deepseek-v4-flash', '你是一个招聘岗位分析专家。从给定的岗位描述(JD)中提取结构化信息。
