INSERT INTO "public"."llm_logs" VALUES ('354115d4-6451-48f6-a439-063fde467d4d', 'parseDocument', 'deepseek-v4-flash', '你是一个文档解析专家。从给定的简历或职位描述中提取结构化信息。
