INSERT INTO "public"."llm_logs" VALUES ('3ecffa7b-d465-41c1-ba06-3ff6b36d70ab', 'parseJobDescription', 'deepseek-v4-flash', '你是一个招聘岗位分析专家。从给定的岗位描述(JD)中提取结构化信息。
