INSERT INTO "public"."llm_logs" VALUES ('819042b1-86ed-4081-9ec4-3fe9464536f0', 'parseJobDescription', 'deepseek-v4-flash', '你是一个招聘岗位分析专家。从给定的岗位描述(JD)中提取结构化信息。
