INSERT INTO "public"."llm_logs" VALUES ('6c59c874-959d-4816-9eb9-58bd71fd12b4', 'extractSkills', 'deepseek-v4-flash', '你是一个技能提取专家。从给定的简历文本中提取所有技能标签，并评估熟练度。

