INSERT INTO "public"."llm_logs" VALUES ('98ab4dcf-f4b7-4cf2-a742-f733cbbcd3e2', 'parseJobDescription', 'deepseek-v4-flash', '你是一个招聘岗位分析专家。从给定的岗位描述(JD)中提取结构化信息。
