INSERT INTO "public"."llm_logs" VALUES ('a0b263f3-084f-4d9e-99ea-169e827fab72', 'extractSkills', 'deepseek-v4-flash', '你是一个技能提取专家。从给定的简历文本中提取所有技能标签，并评估熟练度。

