INSERT INTO "public"."llm_logs" VALUES ('e37e2260-e0a3-419a-9713-1213027716ab', 'parseDocument', 'deepseek-v4-flash', '你是一个文档解析专家。从给定的简历或职位描述中提取结构化信息。
返回纯JSON对象，包含以下字段：
- name: 姓名
