INSERT INTO "public"."llm_logs" VALUES ('3e66f5f0-1391-401e-b0d1-cfe329ebc8e6', 'parseJobDescription', 'deepseek-v4-flash', '你是一个招聘岗位分析专家。从给定的岗位描述(JD)中提取结构化信息。
