INSERT INTO "public"."llm_logs" VALUES ('57218cb4-4d60-4f36-b5c0-56b3899ca3a0', 'parseJobDescription', 'deepseek-v4-flash', '你是一个招聘岗位分析专家。从给定的岗位描述(JD)中提取结构化信息。
返回纯JSON对象，包含以下字段：
